-- Neutral legal-source reference library. All resources start draft and require review before public display.
CREATE TABLE IF NOT EXISTS election_legal_sources(id TEXT PRIMARY KEY,election_type TEXT NOT NULL CHECK(election_type IN ('council','parliament','presidency','other')),title TEXT NOT NULL,topic TEXT NOT NULL CHECK(topic IN ('registration','documents','deadlines','finance','general')),source_url TEXT NOT NULL,issuer TEXT NOT NULL,source_date TEXT NOT NULL DEFAULT '',reviewed_at TEXT NOT NULL DEFAULT '',status TEXT NOT NULL DEFAULT 'draft' CHECK(status IN ('draft','approved','archived')),notes TEXT NOT NULL DEFAULT '',created_by INTEGER,created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE INDEX IF NOT EXISTS idx_legal_sources_public ON election_legal_sources(election_type,status,topic);
CREATE TABLE IF NOT EXISTS election_legal_personal_checks(telegram_id INTEGER NOT NULL REFERENCES candidate_users(telegram_id) ON DELETE CASCADE,source_id TEXT NOT NULL REFERENCES election_legal_sources(id) ON DELETE CASCADE,acknowledged_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,PRIMARY KEY(telegram_id,source_id));
